pub const MANIFEST:&str="{\n  \"backend\": \"webgpu-wgpu-v1\",\n  \"core_semantics\": \"ink-executable-core-v1\",\n  \"core_sha256\": \"e1202e78516ae2d9673021d209b868ae2d4f909a6df65189fc6b566c53fbe602\",\n  \"cpu_c_sha256\": \"6b9cb295d2f0d04bda141f1942bc68f2137d146f3fda34a63c7033c91341932f\",\n  \"functions\": [\n    {\n      \"cpu_reason\": null,\n      \"gpu\": {\n        \"aggregate\": \"sum\",\n        \"list_param\": 0,\n        \"stages\": [\n          {\n            \"kind\": \"map\",\n            \"shader\": \"function_0_stage_0.wgsl\"\n          },\n          {\n            \"kind\": \"filter\",\n            \"shader\": \"function_0_stage_1.wgsl\"\n          }\n        ]\n      },\n      \"index\": 0,\n      \"name\": \"bulk\",\n      \"params\": [\n        {\n          \"name\": \"xs\",\n          \"type\": \"list_u32\"\n        },\n        {\n          \"name\": \"scale\",\n          \"type\": \"u32\"\n        }\n      ],\n      \"result\": \"u32\"\n    },\n    {\n      \"cpu_reason\": \"GPU candidate requires one List<u32> and u32/Bool scalar parameters\",\n      \"gpu\": null,\n      \"index\": 1,\n      \"name\": \"finish\",\n      \"params\": [\n        {\n          \"name\": \"value\",\n          \"type\": \"u32\"\n        },\n        {\n          \"name\": \"bias\",\n          \"type\": \"u32\"\n        }\n      ],\n      \"result\": \"u32\"\n    },\n    {\n      \"cpu_reason\": \"GPU currently supports sum/count results; order-sensitive folds stay on CPU\",\n      \"gpu\": null,\n      \"index\": 2,\n      \"name\": \"entry\",\n      \"params\": [\n        {\n          \"name\": \"xs\",\n          \"type\": \"list_u32\"\n        },\n        {\n          \"name\": \"scale\",\n          \"type\": \"u32\"\n        },\n        {\n          \"name\": \"bias\",\n          \"type\": \"u32\"\n        }\n      ],\n      \"result\": \"u32\"\n    }\n  ],\n  \"limitations\": [\n    \"GPU subset: u32 map/filter followed by sum/count, one list and u32/Bool scalars\",\n    \"u64, exact integers, nested collections, order-sensitive folds and transactions remain on CPU\",\n    \"GPU unavailable, device loss, limits or validation errors fall back to compiled CPU\",\n    \"no universal performance or all-device GPU guarantee\"\n  ],\n  \"proof_claim\": \"no GPU backend or shader correctness proof; no new optimisation laws; literal source stages retained\",\n  \"schema\": 1,\n  \"selection\": \"bounded host-side measurements, including allocation/upload/dispatch/readback; correctness independent of profiles\",\n  \"shaders\": {\n    \"count.wgsl\": \"df4f41caf2ca6f27d91ac65dcdda1c5b8e8ac0b1867ea88f37b2afd02d0cead7\",\n    \"filter-offsets.wgsl\": \"576cb0498f1b6b4684dceedefe773e460dc121d2b6ea9af71553f8a90e9c2e83\",\n    \"filter-scatter.wgsl\": \"06a50fa665a840e417acaeb747fb154bb2a5e9edb37e345b6f2251929137e391\",\n    \"function_0_stage_0.wgsl\": \"0149a8ef93a1302163ddead6b4efd7c82cf03de5fa122d6a2cb6ddcfa2b6cbdb\",\n    \"function_0_stage_1.wgsl\": \"e0fc1be394cea8b351b6be86c39e2a415b50bc5d9964963bafde9ad620be5095\",\n    \"sum.wgsl\": \"52be23c14b27dfb888ff2e26281b34ece5cb1ba7ca83a784e6876c0d369e576b\"\n  },\n  \"trust\": [\n    \"Rust type checker\",\n    \"literal C and WGSL lowering\",\n    \"parallel u32 sum and stable filter primitives\",\n    \"C/LLVM and wgpu/WebGPU shader toolchains and drivers\",\n    \"host ABI and runtime\"\n  ]\n}";
pub const SHADERS:&[(&str,&str)]=&[
("function_0_stage_0.wgsl","@group(0) @binding(0) var<storage,read> input_data:array<u32>;\n@group(0) @binding(1) var<storage,read_write> output_data:array<u32>;\n@group(0) @binding(2) var<storage,read> input_length:u32;\n@group(0) @binding(3) var<storage,read_write> output_length:u32;\n@group(0) @binding(4) var<storage,read> params:array<u32>;\n\n@compute @workgroup_size(256) fn main(@builtin(global_invocation_id) gid:vec3<u32>) {\nif(gid.x==0u){output_length=input_length;}\nif(gid.x<input_length){\noutput_data[gid.x]=((input_data[gid.x] * params[1]) + 7u);\n}\n}"),
("function_0_stage_1.wgsl","@group(0) @binding(0) var<storage,read> input_data:array<u32>;\n@group(0) @binding(1) var<storage,read_write> output_data:array<u32>;\n@group(0) @binding(2) var<storage,read> input_length:u32;\n@group(0) @binding(3) var<storage,read_write> output_length:u32;\n@group(0) @binding(4) var<storage,read> params:array<u32>;\n\n@group(0) @binding(5) var<storage,read_write> prefixes:array<u32>;\n@group(0) @binding(6) var<storage,read_write> counts:array<u32>;\nvar<workgroup> scan:array<u32,256>;\n@compute @workgroup_size(256) fn main(@builtin(global_invocation_id) gid:vec3<u32>,@builtin(local_invocation_id) lid:vec3<u32>,@builtin(workgroup_id) group:vec3<u32>) {\nvar selected=0u;\nif(gid.x<input_length){\nif((input_data[gid.x] > 100u)){selected=1u;}\n}\nscan[lid.x]=selected;\nworkgroupBarrier();\nfor(var stride=1u;stride<256u;stride*=2u){\nvar previous=0u;if(lid.x>=stride){previous=scan[lid.x-stride];}\nworkgroupBarrier();scan[lid.x]+=previous;workgroupBarrier();\n}\nif(gid.x<input_length){prefixes[gid.x]=scan[lid.x];}\nif(lid.x==255u){counts[group.x]=scan[255];}\n}"),
("sum.wgsl","@group(0) @binding(0) var<storage,read> input_data:array<u32>;\n@group(0) @binding(1) var<storage,read_write> output_data:array<u32>;\n@group(0) @binding(2) var<storage,read> input_length:u32;\n@group(0) @binding(3) var<storage,read_write> output_length:u32;\nvar<workgroup> partial:array<u32,256>;\n@compute @workgroup_size(256) fn main(@builtin(global_invocation_id) gid:vec3<u32>,@builtin(local_invocation_id) lid:vec3<u32>,@builtin(workgroup_id) group:vec3<u32>) {\n    var value=0u;\n    if(gid.x<input_length){value=input_data[gid.x];}\n    partial[lid.x]=value;\n    workgroupBarrier();\n    for(var stride=128u;stride>0u;stride/=2u){\n        if(lid.x<stride){partial[lid.x]+=partial[lid.x+stride];}\n        workgroupBarrier();\n    }\n    if(lid.x==0u){output_data[group.x]=partial[0];}\n    if(gid.x==0u){output_length=(input_length+255u)/256u;}\n}\n"),
("count.wgsl","@group(0) @binding(0) var<storage,read> input_length:u32;\n@group(0) @binding(1) var<storage,read_write> output_data:array<u32>;\n@compute @workgroup_size(1) fn main(){output_data[0]=input_length;}\n"),
("filter-offsets.wgsl","@group(0) @binding(0) var<storage,read> counts:array<u32>;\n@group(0) @binding(1) var<storage,read_write> offsets:array<u32>;\n@group(0) @binding(2) var<storage,read_write> output_length:u32;\n@compute @workgroup_size(64) fn main(@builtin(global_invocation_id) gid:vec3<u32>){\n    if(gid.x>=arrayLength(&counts)){return;}\n    // Simple ordered block prefix primitive; selection measures its full cost.\n    var before=0u;for(var block=0u;block<gid.x;block++){before+=counts[block];}\n    offsets[gid.x]=before;\n    if(gid.x+1u==arrayLength(&counts)){output_length=before+counts[gid.x];}\n}\n"),
("filter-scatter.wgsl","@group(0) @binding(0) var<storage,read> input_data:array<u32>;\n@group(0) @binding(1) var<storage,read_write> output_data:array<u32>;\n@group(0) @binding(2) var<storage,read> input_length:u32;\n@group(0) @binding(3) var<storage,read> prefixes:array<u32>;\n@group(0) @binding(4) var<storage,read> offsets:array<u32>;\n@compute @workgroup_size(256) fn main(@builtin(global_invocation_id) gid:vec3<u32>){\n    let i=gid.x;if(i>=input_length){return;}\n    var previous=0u;if(i%256u!=0u){previous=prefixes[i-1u];}\n    let inclusive=prefixes[i];\n    if(inclusive>previous){output_data[offsets[i/256u]+inclusive-1u]=input_data[i];}\n}\n"),
];
